<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Taxonomy;
use App\Domain\Taxonomy\Entity\TaxonomySubjectAlias;use App\Domain\Taxonomy\Repository\TaxonomySubjectAliasRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Taxonomy\Entity\TaxonomySubjectAliasRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineTaxonomySubjectAliasRepository implements TaxonomySubjectAliasRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function save(TaxonomySubjectAlias $alias):void{$record=new TaxonomySubjectAliasRecord();$record->id=$alias->id;$record->subjectId=$alias->subjectId;$record->alias=$alias->alias;$record->normalizedAlias=$alias->normalizedAlias;$record->createdAt=new \DateTimeImmutable('now',new \DateTimeZone('UTC'));$this->entityManager->persist($record);} public function findByNormalizedAlias(string $normalizedAlias):?TaxonomySubjectAlias{$record=$this->entityManager->createQueryBuilder()->select('alias')->from(TaxonomySubjectAliasRecord::class,'alias')->where('alias.normalizedAlias = :normalized')->setParameter('normalized',$normalizedAlias)->getQuery()->getOneOrNullResult();return $record instanceof TaxonomySubjectAliasRecord?new TaxonomySubjectAlias($record->id,$record->subjectId,$record->alias,$record->normalizedAlias):null;} }
